procedure:public.get_financial_year(date.source_code:
DECLARE
  v_year INTEGER := extract(year from p_date);
  v_month INTEGER := extract(month from p_date);
  v_next_year INTEGER;
BEGIN
  IF v_month < 4 THEN
    v_next_year := v_year;
    v_year := v_year - 1;
  ELSE
    v_next_year := v_year + 1;
  END IF;
  RETURN v_year::TEXT || '-' || right(v_next_year::TEXT, 2);
END;

